import unreal

actors = unreal.EditorLevelLibrary.get_all_level_actors()
sky = None
for a in actors:
    if a.get_actor_label() == 'SkyCreator':
        sky = a
        break

# Check all enum values for precipitation spawn mode and render mode
print("=== PrecipitationSpawnMode values ===")
for attr in dir(unreal.PrecipitationSpawnMode):
    if attr.startswith('E_'):
        print(f"  {attr} = {getattr(unreal.PrecipitationSpawnMode, attr)}")

print("\n=== SkyCreatorParticleRenderMode values ===")
for attr in dir(unreal.SkyCreatorParticleRenderMode):
    if attr.startswith('E_'):
        print(f"  {attr} = {getattr(unreal.SkyCreatorParticleRenderMode, attr)}")

