    if 'Subway' in name or 'Floor' in name:
        loc = a.get_actor_location()
        bounds_origin, bounds_extent = a.get_actor_bounds(True)
        print(f"{name}: loc=({loc.x:.0f},{loc.y:.0f},{loc.z:.0f}) bounds=({bounds_origin.x:.0f},{bounds_origin.y:.0f},{bounds_origin.z:.0f}) extent=({bounds_extent.x:.0f},{bounds_extent.y:.0f},{bounds_extent.z:.0f})")
